export const safeJsonParse = <T>(value: string | null): T | null => {
  if (!value) return null;
  try {
    return JSON.parse(value) as T;
  } catch {
    return null;
  }
};

export const storageGet = <T>(key: string): T | null => {
  if (typeof window === "undefined") return null;
  try {
    return safeJsonParse<T>(window.localStorage.getItem(key));
  } catch (error) {
    console.warn("localStorage access denied, using fallback storage");
    // Fallback to sessionStorage or memory for private browsing
    try {
      return safeJsonParse<T>(window.sessionStorage.getItem(key));
    } catch {
      return null;
    }
  }
};

export const storageSet = (key: string, value: unknown) => {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch (error) {
    console.warn("localStorage access denied, using sessionStorage fallback");
    try {
      window.sessionStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Silent fail for private browsing mode
    }
  }
};

export const storageRemove = (key: string) => {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.removeItem(key);
  } catch (error) {
    console.warn("localStorage access denied, trying sessionStorage fallback");
    try {
      window.sessionStorage.removeItem(key);
    } catch {
      // Silent fail for private browsing mode
    }
  }
};
