import { storageGet, storageSet } from "@/lib/storage";

const CONSULTANTS_KEY = "aa_consultants";
const MEETINGS_KEY = "aa_meetings";

export interface Consultant {
  id?: string;
  name: string;
  email: string;
  specialization: string[];
  experience: number;
  rating: number;
  price: number;
  available: boolean;
  languages: string[];
  universities: string[];
  bio: string;
  avatar?: string;
  createdAt: string;
  // Additional fields for dashboard
  totalClients?: number;
  successRate?: number;
  education?: string[];
  achievements?: string[];
  availability?: string[];
}

export interface Meeting {
  id?: string;
  consultantId: string;
  userId: string;
  userName: string;
  userEmail: string;
  date: string;
  duration: number; // minutes
  status: "scheduled" | "completed" | "cancelled";
  notes?: string;
  meetingLink?: string;
  createdAt: string;
}

// Добавить консультанта
export const addConsultant = async (consultant: Omit<Consultant, 'id' | 'createdAt'>) => {
  try {
    const consultants = storageGet<Consultant[]>(CONSULTANTS_KEY) || [];
    const newConsultant: Consultant = {
      ...consultant,
      id: `consultant_${Date.now()}`,
      createdAt: new Date().toISOString()
    };
    consultants.push(newConsultant);
    storageSet(CONSULTANTS_KEY, consultants);
    return newConsultant.id;
  } catch (error) {
    console.error("Error adding consultant:", error);
    return null;
  }
};

// Получить всех консультантов
export const getConsultants = async (): Promise<Consultant[]> => {
  try {
    console.debug("getConsultants: запрос всех консультантов из localStorage");
    const consultants = storageGet<Consultant[]>(CONSULTANTS_KEY) || [];
    console.debug("getConsultants: данные получены", { count: consultants.length });
    return consultants;
  } catch (error) {
    console.error("getConsultants: ошибка получения консультантов", error);
    return [];
  }
};

// Получить консультантов по специализации
export const getConsultantsBySpecialization = async (specialization: string): Promise<Consultant[]> => {
  try {
    const consultants = storageGet<Consultant[]>(CONSULTANTS_KEY) || [];
    return consultants.filter(consultant => 
      consultant.specialization.includes(specialization)
    );
  } catch (error) {
    console.error("Error getting consultants by specialization:", error);
    return [];
  }
};

// Запланировать встречу
export const scheduleMeeting = async (meeting: Omit<Meeting, 'id' | 'createdAt'>) => {
  try {
    const meetings = storageGet<Meeting[]>(MEETINGS_KEY) || [];
    const newMeeting: Meeting = {
      ...meeting,
      id: `meeting_${Date.now()}`,
      createdAt: new Date().toISOString()
    };
    meetings.push(newMeeting);
    storageSet(MEETINGS_KEY, meetings);
    return newMeeting.id;
  } catch (error) {
    console.error("Error scheduling meeting:", error);
    return null;
  }
};

// Получить встречи пользователя
export const getUserMeetings = async (userId: string): Promise<Meeting[]> => {
  try {
    const meetings = storageGet<Meeting[]>(MEETINGS_KEY) || [];
    return meetings.filter(meeting => meeting.userId === userId);
  } catch (error) {
    console.error("Error getting user meetings:", error);
    return [];
  }
};

// Обновить статус встречи
export const updateMeetingStatus = async (meetingId: string, status: Meeting['status'], notes?: string) => {
  try {
    const meetings = storageGet<Meeting[]>(MEETINGS_KEY) || [];
    const meetingIndex = meetings.findIndex(m => m.id === meetingId);
    if (meetingIndex !== -1) {
      meetings[meetingIndex] = {
        ...meetings[meetingIndex],
        status,
        ...(notes && { notes })
      };
      storageSet(MEETINGS_KEY, meetings);
      return true;
    }
    return false;
  } catch (error) {
    console.error("Error updating meeting status:", error);
    return false;
  }
};
